class Solution {
    public int maxProfit(int[] prices) {
        int minimumPrice = prices[0];
        int bestProfit = 0;
        for (int day = 1; day < prices.length; day++) {
            bestProfit = Math.max(bestProfit, prices[day] - minimumPrice);
            minimumPrice = Math.min(minimumPrice, prices[day]);
        }
        return bestProfit;
    }
}
